script.setup:
// MarkovJunior core, ported from mxgmn/MarkovJunior (C#, MIT, (C) 2022 Maxim Gumin):
// Interpreter.cs, Node.cs (sequence/markov), RuleNode.cs, OneNode.cs, AllNode.cs, ParallelNode.cs,
// Rule.cs and SymmetryHelper.cs, 2D only. Fields, potentials, search, path, map, wfc are left out.
const SUBGROUPS = {
  "()": [1, 0, 0, 0, 0, 0, 0, 0], "(x)": [1, 1, 0, 0, 0, 0, 0, 0], "(y)": [1, 0, 0, 0, 0, 1, 0, 0],
  "(x)(y)": [1, 1, 0, 0, 1, 1, 0, 0], "(xy+)": [1, 0, 1, 0, 1, 0, 1, 0], "(xy)": [1, 1, 1, 1, 1, 1, 1, 1],
};
function getSymmetry(s, dflt) {
  if (s == null) return dflt;
  const r = SUBGROUPS[s];
  if (!r) throw new Error(`unknown symmetry ${s}`);
  return r;
}
// Tiny XML reader for the model files: elements, attributes, comments.
function parseXml(src) {
  src = src.replace(/<!--[\s\S]*?-->/g, "");
  const root = { name: "#root", attrs: {}, children: [] }, stack = [root];
  const re = /<(\/?)([A-Za-z_][\w-]*)([^>]*?)(\/?)>/g;
  let m;
  while ((m = re.exec(src))) {
    const [, close, name, rest, self] = m;
    if (close) { stack.pop(); continue; }
    const attrs = {};
    rest.replace(/([\w-]+)\s*=\s*"([^"]*)"/g, (_, k, v) => { attrs[k] = v; return ""; });
    const el = { name, attrs, children: [] };
    stack[stack.length - 1].children.push(el);
    if (!self) stack.push(el);
  }
  return root.children[0];
}
function rng(seed) {
  let a = seed >>> 0;
  return {
    next() { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; },
    int(n) { return Math.floor(this.next() * n); },
  };
}

class Rule {
  constructor(input, IMX, IMY, output, OMX, OMY, C, p) {
    Object.assign(this, { input, IMX, IMY, output, OMX, OMY, C, p });
    this.ishifts = [];
    for (let c = 0; c < C; c++) this.ishifts.push([]);
    for (let y = 0; y < IMY; y++) for (let x = 0; x < IMX; x++) {
      let w = input[x + y * IMX];
      for (let c = 0; c < C; c++, w >>= 1) if (w & 1) this.ishifts[c].push(x, y);
    }
  }
  zRotated() {
    const { IMX, IMY, OMX, OMY } = this;
    const ni = new Int32Array(this.input.length), no = new Uint8Array(this.output.length);
    for (let y = 0; y < IMX; y++) for (let x = 0; x < IMY; x++) ni[x + y * IMY] = this.input[IMX - 1 - y + x * IMX];
    for (let y = 0; y < OMX; y++) for (let x = 0; x < OMY; x++) no[x + y * OMY] = this.output[OMX - 1 - y + x * OMX];
    return new Rule(ni, IMY, IMX, no, OMY, OMX, this.C, this.p);
  }
  reflected() {
    const { IMX, IMY, OMX, OMY } = this;
    const ni = new Int32Array(this.input.length), no = new Uint8Array(this.output.length);
    for (let y = 0; y < IMY; y++) for (let x = 0; x < IMX; x++) ni[x + y * IMX] = this.input[IMX - 1 - x + y * IMX];
    for (let y = 0; y < OMY; y++) for (let x = 0; x < OMX; x++) no[x + y * OMX] = this.output[OMX - 1 - x + y * OMX];
    return new Rule(ni, IMX, IMY, no, OMX, OMY, this.C, this.p);
  }
  static same(a, b) {
    if (a.IMX !== b.IMX || a.IMY !== b.IMY || a.OMX !== b.OMX || a.OMY !== b.OMY) return false;
    for (let i = 0; i < a.input.length; i++) if (a.input[i] !== b.input[i]) return false;
    for (let i = 0; i < a.output.length; i++) if (a.output[i] !== b.output[i]) return false;
    return true;
  }
  symmetries(sym) {
    const t = [this];
    t[1] = t[0].reflected(); t[2] = t[0].zRotated(); t[3] = t[2].reflected();
    t[4] = t[2].zRotated(); t[5] = t[4].reflected(); t[6] = t[4].zRotated(); t[7] = t[6].reflected();
    const out = [];
    for (let i = 0; i < 8; i++) if (sym[i] && !out.some((s) => Rule.same(s, t[i]))) out.push(t[i]);
    return out;
  }
  static parse(s) {
    const lines = s.split("/");
    const MY = lines.length, MX = lines[0].length;
    if (lines.some((l) => l.length !== MX)) throw new Error(`non-rectangular pattern ${s}`);
    return { chars: lines.join(""), MX, MY };
  }
  static load(attrs, grid) {
    const inp = Rule.parse(attrs.in), out = Rule.parse(attrs.out);
    if (inp.MX !== out.MX || inp.MY !== out.MY) throw new Error(`in "${attrs.in}" and out "${attrs.out}" differ in size`);
    const input = Int32Array.from(inp.chars, (ch) => {
      const w = grid.waves[ch];
      if (w === undefined) throw new Error(`unknown input value ${ch}`);
      return w;
    });
    const output = Uint8Array.from(out.chars, (ch) => {
      if (ch === "*") return 0xff;
      const v = grid.values[ch];
      if (v === undefined) throw new Error(`unknown output value ${ch}`);
      return v;
    });
    return new Rule(input, inp.MX, inp.MY, output, out.MX, out.MY, grid.C, attrs.p != null ? parseFloat(attrs.p) : 1);
  }
}

class Grid {
  constructor(xml, MX, MY) {
    const chars = xml.attrs.values;
    this.MX = MX; this.MY = MY; this.C = chars.length; this.characters = chars;
    this.state = new Uint8Array(MX * MY); this.mask = new Uint8Array(MX * MY);
    this.values = {}; this.waves = {};
    for (let i = 0; i < chars.length; i++) { this.values[chars[i]] = i; this.waves[chars[i]] = 1 << i; }
    this.waves["*"] = (1 << this.C) - 1;
    for (const u of xml.children.filter((c) => c.name === "union")) {
      let w = 0;
      for (const ch of u.attrs.values) w |= this.waves[ch];
      this.waves[u.attrs.symbol] = w;
    }
  }
  matches(rule, x, y) {
    const { MX, state } = this, inp = rule.input;
    let dx = 0, dy = 0;
    for (let di = 0; di < inp.length; di++) {
      if ((inp[di] & (1 << state[x + dx + (y + dy) * MX])) === 0) return false;
      if (++dx === rule.IMX) { dx = 0; dy++; }
    }
    return true;
  }
}

const NODE_NAMES = ["one", "all", "prl", "markov", "sequence"];
function factory(xml, sym, ip) {
  const N = { one: OneNode, all: AllNode, prl: ParallelNode, markov: MarkovNode, sequence: SequenceNode }[xml.name];
  if (!N) throw new Error(`node "${xml.name}" is not supported in this port`);
  const node = new N(ip);
  node.load(xml, sym);
  return node;
}

class Branch {
  constructor(ip) { this.ip = ip; this.parent = null; this.nodes = []; this.n = 0; }
  load(xml, parentSym) {
    const sym = getSymmetry(xml.attrs.symmetry, parentSym);
    for (const c of xml.children) {
      if (!NODE_NAMES.includes(c.name)) continue;
      const child = factory(c, sym, this.ip);
      if (child instanceof Branch) child.parent = this;
      this.nodes.push(child);
    }
  }
  go() {
    for (; this.n < this.nodes.length; this.n++) {
      const node = this.nodes[this.n];
      if (node instanceof Branch) this.ip.current = node;
      if (node.go()) return true;
    }
    this.ip.current = this.ip.current.parent;
    this.reset();
    return false;
  }
  reset() { for (const node of this.nodes) node.reset(); this.n = 0; }
}
class SequenceNode extends Branch {}
class MarkovNode extends Branch {
  go() { this.n = 0; return super.go(); }
}

class RuleNode {
  constructor(ip) { this.ip = ip; this.grid = ip.grid; this.matches = []; this.matchCount = 0; this.lastMatchedTurn = -1; this.counter = 0; }
  load(xml, parentSym) {
    const sym = getSymmetry(xml.attrs.symmetry, parentSym);
    const xrules = xml.children.filter((c) => c.name === "rule");
    const rules = [];
    for (const xr of xrules.length ? xrules : [xml]) {
      const rule = Rule.load(xr.attrs, this.grid);
      for (const r of rule.symmetries(getSymmetry(xr.attrs.symmetry, sym))) rules.push(r);
    }
    this.rules = rules;
    this.steps = xml.attrs.steps ? parseInt(xml.attrs.steps, 10) : 0;
    this.matchMask = rules.map(() => new Uint8Array(this.grid.state.length));
  }
  reset() { this.lastMatchedTurn = -1; this.counter = 0; }
  add(r, x, y, maskr) {
    maskr[x + y * this.grid.MX] = 1;
    // Matches are packed as (r, x, y) triples.
    const k = this.matchCount * 3;
    this.matches[k] = r; this.matches[k + 1] = x; this.matches[k + 2] = y;
    this.matchCount++;
  }
  go() {
    if (this.steps > 0 && this.counter >= this.steps) return false;
    const { grid, ip, rules } = this, { MX, MY, state } = grid;
    if (this.lastMatchedTurn >= 0) {
      const ch = ip.changes;
      for (let n = ip.first[this.lastMatchedTurn] * 2; n < ch.length; n += 2) {
        const x = ch[n], y = ch[n + 1], value = state[x + y * MX];
        for (let r = 0; r < rules.length; r++) {
          const rule = rules[r], maskr = this.matchMask[r], shifts = rule.ishifts[value];
          for (let l = 0; l < shifts.length; l += 2) {
            const sx = x - shifts[l], sy = y - shifts[l + 1];
            if (sx < 0 || sy < 0 || sx + rule.IMX > MX || sy + rule.IMY > MY) continue;
            if (!maskr[sx + sy * MX] && grid.matches(rule, sx, sy)) this.add(r, sx, sy, maskr);
          }
        }
      }
    } else {
      this.matchCount = 0;
      for (let r = 0; r < rules.length; r++) {
        const rule = rules[r], maskr = this.matchMask[r];
        for (let y = rule.IMY - 1; y < MY; y += rule.IMY) for (let x = rule.IMX - 1; x < MX; x += rule.IMX) {
          const shifts = rule.ishifts[state[x + y * MX]];
          for (let l = 0; l < shifts.length; l += 2) {
            const sx = x - shifts[l], sy = y - shifts[l + 1];
            if (sx < 0 || sy < 0 || sx + rule.IMX > MX || sy + rule.IMY > MY) continue;
            if (grid.matches(rule, sx, sy)) this.add(r, sx, sy, maskr);
          }
        }
      }
    }
    return true;
  }
}

class OneNode extends RuleNode {
  reset() {
    super.reset();
    if (this.matchCount !== 0) { for (const m of this.matchMask) m.fill(0); this.matchCount = 0; }
  }
  apply(rule, x, y) {
    const { MX, state } = this.grid, changes = this.ip.changes;
    for (let dy = 0; dy < rule.OMY; dy++) for (let dx = 0; dx < rule.OMX; dx++) {
      const v = rule.output[dx + dy * rule.OMX];
      if (v === 0xff) continue;
      const sx = x + dx, sy = y + dy, si = sx + sy * MX;
      if (state[si] !== v) { state[si] = v; changes.push(sx, sy); }
    }
  }
  go() {
    if (!super.go()) return false;
    this.lastMatchedTurn = this.ip.counter;
    const m = this.matches, MX = this.grid.MX, random = this.ip.random;
    while (this.matchCount > 0) {
      const i = random.int(this.matchCount) * 3, last = (this.matchCount - 1) * 3;
      const r = m[i], x = m[i + 1], y = m[i + 2];
      this.matchMask[r][x + y * MX] = 0;
      m[i] = m[last]; m[i + 1] = m[last + 1]; m[i + 2] = m[last + 2];
      this.matchCount--;
      if (this.grid.matches(this.rules[r], x, y)) { this.apply(this.rules[r], x, y); this.counter++; return true; }
    }
    return false;
  }
}

class AllNode extends RuleNode {
  reset() {
    super.reset();
    if (this.matchCount !== 0) { for (const m of this.matchMask) m.fill(0); this.matchCount = 0; }
  }
  fit(r, x, y) {
    const rule = this.rules[r], { MX, state, mask } = this.grid;
    for (let dy = 0; dy < rule.OMY; dy++) for (let dx = 0; dx < rule.OMX; dx++) {
      if (rule.output[dx + dy * rule.OMX] !== 0xff && mask[x + dx + (y + dy) * MX]) return;
    }
    for (let dy = 0; dy < rule.OMY; dy++) for (let dx = 0; dx < rule.OMX; dx++) {
      const v = rule.output[dx + dy * rule.OMX];
      if (v === 0xff) continue;
      const i = x + dx + (y + dy) * MX;
      mask[i] = 1; state[i] = v; this.ip.changes.push(x + dx, y + dy);
    }
  }
  go() {
    if (!super.go()) return false;
    const ip = this.ip;
    this.lastMatchedTurn = ip.counter;
    if (this.matchCount === 0) return false;
    const MX = this.grid.MX, m = this.matches, count = this.matchCount;
    // Random permutation (the "inside-out" shuffle MJ uses).
    const order = new Int32Array(count);
    for (let i = 0; i < count; i++) { const j = ip.random.int(i + 1); order[i] = order[j]; order[j] = i; }
    for (let k = 0; k < count; k++) {
      const i = order[k] * 3, r = m[i], x = m[i + 1], y = m[i + 2];
      this.matchMask[r][x + y * MX] = 0;
      this.fit(r, x, y);
    }
    const ch = ip.changes, mask = this.grid.mask;
    for (let n = ip.first[this.lastMatchedTurn] * 2; n < ch.length; n += 2) mask[ch[n] + ch[n + 1] * MX] = 0;
    this.counter++;
    this.matchCount = 0;
    return true;
  }
}

class ParallelNode extends RuleNode {
  load(xml, sym) { super.load(xml, sym); this.newstate = new Uint8Array(this.grid.state.length); }
  add(r, x, y) {
    const rule = this.rules[r], { MX, state } = this.grid;
    if (this.ip.random.next() > rule.p) return;
    for (let dy = 0; dy < rule.OMY; dy++) for (let dx = 0; dx < rule.OMX; dx++) {
      const v = rule.output[dx + dy * rule.OMX], i = x + dx + (y + dy) * MX;
      if (v !== 0xff && v !== state[i]) { this.newstate[i] = v; this.ip.changes.push(x + dx, y + dy); }
    }
    this.matchCount++;
  }
  go() {
    if (!super.go()) return false;
    const ip = this.ip, ch = ip.changes, MX = this.grid.MX;
    for (let n = ip.first[ip.counter] * 2; n < ch.length; n += 2) {
      const i = ch[n] + ch[n + 1] * MX;
      this.grid.state[i] = this.newstate[i];
    }
    this.counter++;
    return this.matchCount > 0;
  }
}

class Interpreter {
  constructor(xmlText, MX, MY) {
    const xml = parseXml(xmlText);
    this.origin = xml.attrs.origin === "True";
    this.grid = new Grid(xml, MX, MY);
    const sym = getSymmetry(xml.attrs.symmetry, [1, 1, 1, 1, 1, 1, 1, 1]);
    const top = factory(xml, sym, this);
    if (top instanceof Branch) this.root = top;
    else { this.root = new MarkovNode(this); this.root.nodes = [top]; }
  }
  start(seed) {
    const g = this.grid;
    this.random = rng(seed);
    g.state.fill(0); g.mask.fill(0);
    if (this.origin) g.state[(g.MX >> 1) + (g.MY >> 1) * g.MX] = 1;
    this.changes = []; this.first = [0];
    this.root.reset();
    this.current = this.root;
    this.counter = 0;
  }
  get done() { return this.current == null; }
  /** One MarkovJunior turn. Returns false once the program has finished. */
  step() {
    if (!this.current) return false;
    this.current.go();
    this.counter++;
    this.first.push(this.changes.length / 2);
    return true;
  }
}

// Models from mxgmn/MarkovJunior models/ (verbatim), with the colors of resources/palette.xml.
const MODELS = [
  { name: "MazeGrowth", rows: [31, 59, 101], odd: true, perCell: 0.024, xml: `<one values="BWA" in="WBB" out="WAW" origin="True"/>` },
  { name: "MazeBacktracker", rows: [31, 59, 101], odd: true, perCell: 0.05, xml: `<markov values="BRGW" origin="True">
  <one in="RBB" out="GGR"/>
  <one in="RGG" out="WWR"/>
</markov>` },
  { name: "River", rows: [40, 64, 96], perCell: 0.16, xml: `<sequence values="BWRUGE">
  <one in="B" out="W" steps="1"/>
  <one in="B" out="R" steps="1"/>
  <one>
    <rule in="RB" out="RR"/>
    <rule in="WB" out="WW"/>
  </one>
  <all in="RW" out="UU"/>
  <all>
    <rule in="W" out="B"/>
    <rule in="R" out="B"/>
  </all>
  <all in="UB" out="UU" steps="1"/>
  <all in="BU/UB" out="U*/**"/>
  <all in="UB" out="*G"/>
  <one in="B" out="E" steps="13"/>
  <one>
    <rule in="EB" out="*E"/>
    <rule in="GB" out="*G"/>
  </one>
</sequence>` },
  { name: "Flowers", rows: [40, 60, 90], perCell: 0.011, xml: `<sequence values="NGUEPY" symmetry="(x)">
  <all in="N/*/*/*" out="G/*/*/*"/>
  <all in="G/*/*/*/*" out="U/*/*/*/*"/>
  <markov>
    <one>
      <rule in="UUU/UUU/UPU" out="***/*P*/*E*"/>
      <rule in="UUU/UUU/UUU/PUU/**U" out="***/*P*/*E*/EE*/***"/>
      <rule in="UUUUU/UUUUU/UUUUU/UUPUU/U***U" out="*****/*P*P*/*E*E*/*EEE*/*****"/>
      <rule in="UUU/UPU/UEU/UEU" out="*Y*/YEY/*Y*/***"/>
    </one>
    <one in="UUUUU/UUUUU/UUUUU/GGGGG/NNNNN" out="*****/**P**/**E**/**E**/**E**"/>
  </markov>
  <all in="***/*P*/***" out="*Y*/YEY/*Y*"/>
</sequence>` },
  // Runs forever in MJ too (the repo renders 100 steps); here it starts over after a while.
  { name: "BasicSnake", rows: [15, 23, 31], odd: true, rate: 14, maxTurns: 1400, xml: `<sequence values="BWDPGR" origin="True">
  <all>
    <rule in="WBB" out="**D"/>
    <rule in="DBB" out="**D"/>
  </all>
  <one in="WBD" out="PGR"/>
  <one in="RBD" out="GGR" steps="2"/>
  <one in="D" out="W" steps="15"/>
  <markov>
    <one in="RBW" out="GGR"/>
    <all>
      <rule in="RBD" out="GGR"/>
      <rule in="PGG" out="DBP"/>
    </all>
  </markov>
</sequence>` },
];
const PALETTE = { B: "000000", I: "1D2B53", P: "7E2553", E: "008751", N: "AB5236", D: "5F574F", A: "C2C3C7", W: "FFF1E8", R: "FF004D", O: "FFA300", Y: "FFEC27", G: "00E436", U: "29ADFF", S: "83769C", K: "FF77A8", F: "FFCCAA" };
const hex = (h) => [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);

const gl = ctx.gl;
const fs = `#version 300 es
precision highp float;
out vec4 outColor;
uniform sampler2D u_grid;      // r = value / 255, g = recent-change glow
uniform vec3 u_pal[16];
uniform vec2 u_resolution, u_origin, u_cells;
uniform float u_cell, u_glowOn;
void main() {
  vec2 p = vec2(gl_FragCoord.x, u_resolution.y - gl_FragCoord.y) - u_origin;   // top-left origin, like MJ
  vec2 size = u_cells * u_cell;
  vec2 c = floor(p / u_cell);
  // Backdrop: dark, with a soft drop shadow under the board.
  vec2 q = (gl_FragCoord.xy - 0.5 * u_resolution) / u_resolution.y;
  vec3 bg = mix(vec3(0.075, 0.078, 0.095), vec3(0.03, 0.03, 0.04), smoothstep(0.2, 1.1, length(q)));
  vec2 d = max(max(-p, p - size), 0.0);
  float shadow = exp(-length(d) / max(12.0, u_cell * 3.0));
  bg *= 1.0 - 0.55 * shadow * step(0.001, length(d));
  if (any(lessThan(c, vec2(0.0))) || any(greaterThanEqual(c, u_cells))) {
    float rim = 1.0 - smoothstep(0.0, 1.5, length(d));
    outColor = vec4(bg + rim * 0.08, 1.0);
    return;
  }
  vec4 t = texelFetch(u_grid, ivec2(c), 0);
  vec3 col = u_pal[int(t.r * 255.0 + 0.5)];
  col = mix(col, vec3(1.0, 0.97, 0.9), t.g * 0.55 * u_glowOn);
  // Large cells get a faint bevel so the grid reads as pixels.
  vec2 f = fract(p / u_cell);
  float edge = step(6.0, u_cell) * (1.0 - smoothstep(0.0, 1.5 / u_cell, min(min(f.x, f.y), min(1.0 - f.x, 1.0 - f.y))));
  col *= 1.0 - 0.07 * edge;
  outColor = vec4(col, 1.0);
}`;
const program = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs);
const tex = gl.createTexture();
Object.assign(ctx.state, { MODELS, PALETTE, hex, program, tex, Interpreter, key: "", seed: 1 + Math.floor(Math.random() * 1e9) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const mi = Math.min(s.MODELS.length - 1, Math.max(0, Math.round(u.u_model)));
const model = s.MODELS[mi], si = Math.min(2, Math.max(0, Math.round(u.u_size)));
// The grid follows the canvas's shape (landscape or portrait); a new shape starts a new board.
const aspect = Math.min(2.4, Math.max(1 / 2.4, w / h));
const key = mi + "|" + si + "|" + Math.round(aspect * 10);
const start = () => {
  const ip = s.ip, g = ip.grid;
  ip.start(s.seed++);
  s.glow.fill(0); s.doneAt = -1; s.acc = 0; s.turns = 0;
  for (let i = 0; i < g.state.length; i++) { s.pixels[i * 2] = g.state[i]; s.pixels[i * 2 + 1] = 0; }
  s.uploaded = 0;
};
if (key !== s.key) {
  // New model or size: the grid takes the canvas's shape so the board fills the frame.
  s.key = key;
  const n = model.rows[si];
  let MX = aspect >= 1 ? Math.max(n, Math.round(n * aspect * 0.97)) : n;
  let MY = aspect >= 1 ? n : Math.round(n / aspect * 0.97);
  if (model.odd && MY % 2 === 0) MY--;
  if (model.odd && MX % 2 === 0) MX--;
  s.ip = new s.Interpreter(model.xml, MX, MY);
  s.MX = MX; s.MY = MY;
  s.glow = new Float32Array(MX * MY);
  s.pixels = new Uint8Array(MX * MY * 2);
  const pal = new Float32Array(48);
  [...s.ip.grid.characters].forEach((ch, i) => pal.set(s.hex(s.PALETTE[ch] ?? "FF00FF"), i * 3));
  s.pal = pal;
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RG8, MX, MY, 0, gl.RG, gl.UNSIGNED_BYTE, null);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
  start();
}
const ip = s.ip, g = ip.grid, MX = s.MX, MY = s.MY;
if (u.u_restart || (s.doneAt >= 0 && ctx.time - s.doneAt > 3)) start();

// Run MarkovJunior turns at the model's pace, within a time budget so the frame stays smooth.
if (s.doneAt < 0) {
  const pace = model.rate ?? model.perCell * MX * MY;
  s.acc = Math.min(s.acc + pace * u.u_speed * Math.min(ctx.dt, 0.05), 50000);
  const from = ip.changes.length, t0 = performance.now();
  while (s.acc >= 1) {
    s.acc--;
    if (!ip.step() || ip.done || (model.maxTurns && s.turns >= model.maxTurns * (si + 1))) { s.doneAt = ctx.time; s.acc = 0; break; }
    s.turns++;
    if ((s.turns & 63) === 0 && performance.now() - t0 > 10) { s.acc = Math.min(s.acc, 2); break; }
  }
  const ch = ip.changes;
  for (let n = from; n < ch.length; n += 2) s.glow[ch[n] + ch[n + 1] * MX] = 1;
  // Long runs: keep the change log short; nodes only read it back to their last turn.
  if (ch.length > 4e6) { s.seed--; start(); }
}
const fade = Math.exp(-ctx.dt * 3.5);
for (let i = 0; i < MX * MY; i++) {
  s.pixels[i * 2] = g.state[i];
  const v = s.glow[i] *= fade;
  s.pixels[i * 2 + 1] = v * 255;
}
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, MX, MY, gl.RG, gl.UNSIGNED_BYTE, s.pixels);

// Fit the board with a margin; whole-pixel cells once they are big enough to stay crisp.
let cell = Math.min((w * 0.92) / MX, (h * 0.9) / MY);
if (cell >= 3) cell = Math.floor(cell);
const ox = Math.round((w - MX * cell) / 2), oy = Math.round((h - MY * cell) / 2);
gl.useProgram(s.program);
ctx.utils.bindTexture(s.program, "u_grid", s.tex, 0);
ctx.utils.drawFullscreen(s.program, { u_pal: s.pal, u_origin: [ox, oy], u_cells: [MX, MY], u_cell: cell, u_glowOn: u.u_glow ? 1 : 0 });
ctx.publish("model", model.name);
ctx.publish("grid", `${MX}×${MY}`);
ctx.publish("turn", ip.counter);
ctx.publish("state", s.doneAt >= 0 ? "finished" : "running");
